Account.ready.then(async user=>{if(user.role!=='admin'){location.replace('/sets.html');return;}
 const el=(tag,text)=>{const x=document.createElement(tag);if(text!==undefined)x.textContent=text;return x};
 async function load(){try{const rows=await Account.request('/api/admin/editor-proposals');const list=document.getElementById('proposals');list.replaceChildren();document.getElementById('message').textContent=rows.filter(r=>r.status==='Pending').length+' pending proposals.';
 for(const p of rows){const card=el('section');card.className='proposal';card.append(el('h2','#'+p.id+' · '+p.kind+' '+(p.after_body.display_code||p.target_id)+' · '+p.status),el('p','Submitted by '+p.author+' · '+p.created));
 for(const key of Object.keys(p.after_body)){if(JSON.stringify(p.before_body[key])===JSON.stringify(p.after_body[key]))continue;card.append(el('h3',key==='choices'?'Answer choices':key));const diff=el('div');diff.className='diff';for(const [label,v] of [['Before',p.before_body[key]],['Proposed',p.after_body[key]]]){const col=el('div');col.append(el('strong',label),el('pre',key==='choices'?v.map(c=>c.id+'. '+c.text).join('\n'):String(v||'')));diff.append(col)}card.append(diff)}
 if(p.status==='Pending'){const label=el('label','Review note (optional)'),note=el('textarea');note.rows=3;note.maxLength=2000;label.append(note);const status=el('p');status.setAttribute('role','status');card.append(label);const buttons=[];for(const decision of ['Approved','Rejected']){const b=el('button',decision==='Approved'?'Approve and update bank':'Reject proposal');b.className=decision==='Approved'?'primary':'secondary';buttons.push(b);b.onclick=async()=>{buttons.forEach(x=>x.disabled=true);status.textContent='Creating verified backup…';try{await Account.request('/api/admin/editor-review',{id:p.id,decision,note:note.value});await load()}catch(e){status.textContent=e.message;buttons.forEach(x=>x.disabled=false)}};card.append(b)}card.append(status)}else card.append(el('p','Reviewed: '+p.reviewed+(p.review_note?' · '+p.review_note:'')));list.append(card)}
 }catch(e){document.getElementById('message').textContent=e.message}}
 document.getElementById('refresh').onclick=load;await load();}).catch(()=>{});
